6. Multi-Language Implementations: The Universal Base Converter & Roman Parser
Below is a complete, production-grade interactive multi-language program that demonstrates: 1. Converting arbitrary integers between any source base \(b_1\) and target base \(b_2\) (\(2 \le b \le 36\)). 2. Parsing and formatting Roman numerals with vinculum support for numbers exceeding \(3,999\).

Python 3C++20JuliaModern FortranMATLAB / OctaveLean 4


import math

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def base_to_decimal(s: str, base: int) -&gt; int:
    """Horner's method for arbitrary base string to integer."""
    val = 0
    for char in s.upper():
        digit = DIGITS.index(char)
        if digit &gt;= base:
            raise ValueError(f"Invalid digit '{char}' for base {base}")
        val = val * base + digit
    return val

def decimal_to_base(n: int, base: int) -&gt; str:
    """Successive Euclidean division from decimal integer to target base."""
    if n == 0:
        return "0"
    digits = []
    curr = n
    while curr &gt; 0:
        curr, rem = divmod(curr, base)
        digits.append(DIGITS[rem])
    return "".join(reversed(digits))

def int_to_roman_vinculum(n: int) -&gt; str:
    """Convert positive integer to Roman numerals with vinculum for &gt;= 4000."""
    mapping = [
        (1000000, "M̄"), (900000, "C̄M̄"), (500000, "D̄"), (400000, "C̄D̄"),
        (100000, "C̄"), (90000, "X̄C̄"), (50000, "L̄"), (40000, "X̄L̄"),
        (10000, "X̄"), (9000, "ĪX̄"), (5000, "V̄"), (4000, "ĪV̄"),
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]
    res = []
    curr = n
    for val, roman in mapping:
        while curr &gt;= val:
            res.append(roman)
            curr -= val
    return "".join(res)

if __name__ == "__main__":
    test_val = 305470
    print(f"Decimal: {test_val}")
    print(f"Binary:  {decimal_to_base(test_val, 2)}")
    print(f"Hex:     {decimal_to_base(test_val, 16)}")
    print(f"Base 36: {decimal_to_base(test_val, 36)}")
    print(f"Roman Vinculum: {int_to_roman_vinculum(test_val)}")


#include &lt;iostream&gt;
