#include &lt;vector&gt;
#include &lt;algorithm&gt;
#include &lt;stdexcept&gt;

const std::string DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

long long base_to_decimal(const std::string& s, int base) {
    long long val = 0;
    for (char c : s) {
        size_t idx = DIGITS.find(std::toupper(c));
        if (idx == std::string::npos || idx &gt;= static_cast&lt;size_t&gt;(base)) {
            throw std::invalid_argument("Invalid digit for base");
        }
        val = val * base + idx;
    }
    return val;
}

std::string decimal_to_base(long long n, int base) {
    if (n == 0) return "0";
    std::string res = "";
    while (n &gt; 0) {
        res += DIGITS[n % base];
        n /= base;
    }
    std::reverse(res.begin(), res.end());
    return res;
}

int main() {
    long long num = 755;
    std::cout &lt;&lt; "C++20 Base Conversions for " &lt;&lt; num &lt;&lt; ":\n";
    std::cout &lt;&lt; "Binary: " &lt;&lt; decimal_to_base(num, 2) &lt;&lt; "\n";
    std::cout &lt;&lt; "Hex:    " &lt;&lt; decimal_to_base(num, 16) &lt;&lt; "\n";
    std::cout &lt;&lt; "Reconstructed: " &lt;&lt; base_to_decimal("2F3", 16) &lt;&lt; "\n";
    return 0;
}


# Julia 1.10: Radix Conversion & Horner's Rule
const DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

function base_to_dec(str::String, base::Int)::BigInt
    val = BigInt(0)
    for c in uppercase(str)
        idx = findfirst(==(c), DIGITS) - 1
        val = val * base + idx
    end
    return val
end

function dec_to_base(n::BigInt, base::Int)::String
    n == 0 && return "0"
    chars = Char[]
    curr = n
    while curr &gt; 0
        rem = curr % base
        push!(chars, DIGITS[rem + 1])
        curr ÷= base
    end
    return String(reverse(chars))
end

num = BigInt(305470)
println("Julia: Converting $num to Sexagesimal equivalent check:")
println("Hex: ", dec_to_base(num, 16))
println("Back: ", base_to_dec("4A93E", 16))


program base_converter
    implicit none
    integer :: n, base, rem, i, pos
    character(len=64) :: buffer
    character(len=36), parameter :: digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    n = 755
    base = 16
    buffer = ''
    pos = len(buffer)

    print *, 'Fortran 2018: Decimal to Base Conversion'
    do while (n &gt; 0)
        rem = mod(n, base)
        buffer(pos:pos) = digits(rem+1:rem+1)
        pos = pos - 1
        n = n / base
    end do

    print *, 'Result in Hex: ', trim(adjustl(buffer(pos+1:)))
end program base_converter


% MATLAB / GNU Octave: Arbitrary Base Converter
function out_str = dec2base_custom(n, target_base)
    digits_map = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    if n == 0
        out_str = '0';
        return;
    end
    chars = [];
    curr = n;
    while curr &gt; 0
        r = mod(curr, target_base);
        chars = [digits_map(r + 1), chars];
        curr = floor(curr / target_base);
    end
    out_str = chars;
end


-- Lean 4: Formal Verification of Positional Number Evaluation
import Mathlib.Data.Nat.Basic
import Mathlib.Data.List.Basic

-- Horner's polynomial evaluation function for list of digits in base b
def evalDigits (b : ℕ) : List ℕ → ℕ
  | [] =&gt; 0
  | d :: ds =&gt; d + b * evalDigits b ds

-- Theorem: Single digit evaluates directly to itself in any valid base
theorem eval_single_digit (b d : ℕ) : evalDigits b [d] = d := by
  simp [evalDigits]

4. Multi-Language Implementations: Adaptive 4th-Order Runge-Kutta (RK4) Orbital Solver
To demonstrate the bridge between analytical mechanics and computational physics, below is an interactive multi-language implementation of the Classical 4th-Order Runge-Kutta (RK4) integrator simulating non-linear gravitational planetary orbits (\(\ddot{\mathbf{r}} = -G M \frac{\mathbf{r}}{\|\mathbf{r}\|^3}\)):

Python 3C++20JuliaModern FortranMATLAB / OctaveLean 4


import numpy as np

def gravitational_accel(r, GM=1.0):
    norm_r = np.linalg.norm(r)
    return -GM * r / (norm_r**3)

def rk4_step(r, v, dt, GM=1.0):
    # State: [r, v] where dr/dt = v, dv/dt = a(r)
    k1_r = v
    k1_v = gravitational_accel(r, GM)

    k2_r = v + 0.5 * dt * k1_v
    k2_v = gravitational_accel(r + 0.5 * dt * k1_r, GM)

    k3_r = v + 0.5 * dt * k2_v
    k3_v = gravitational_accel(r + 0.5 * dt * k2_r, GM)

    k4_r = v + dt * k3_v
    k4_v = gravitational_accel(r + dt * k3_r, GM)

    r_next = r + (dt / 6.0) * (k1_r + 2*k2_r + 2*k3_r + k4_r)
    v_next = v + (dt / 6.0) * (k1_v + 2*k2_v + 2*k3_v + k4_v)
    return r_next, v_next

if __name__ == "__main__":
    # Initial conditions: circular/elliptical orbit
    r = np.array([1.0, 0.0])
    v = np.array([0.0, 1.0])
    dt = 0.01

    for step in range(500):
        r, v = rk4_step(r, v, dt)

    print(f"Python 3 RK4 Orbit: Final Position = {r}, Final Velocity = {v}")


#include &lt;iostream&gt;
#include &lt;array&gt;
#include &lt;cmath&gt;

using Vec2 = std::array&lt;double, 2&gt;;

Vec2 accel(const Vec2& r, double GM = 1.0) {
    double dist = std::sqrt(r[0]*r[0] + r[1]*r[1]);
    double factor = -GM / (dist * dist * dist);
    return {factor * r[0], factor * r[1]};
}

void rk4_step(Vec2& r, Vec2& v, double dt, double GM = 1.0) {
    Vec2 k1_r = v;
    Vec2 k1_v = accel(r, GM);

    Vec2 r_mid1 = {r[0] + 0.5 * dt * k1_r[0], r[1] + 0.5 * dt * k1_r[1]};
    Vec2 v_mid1 = {v[0] + 0.5 * dt * k1_v[0], v[1] + 0.5 * dt * k1_v[1]};
    Vec2 k2_r = v_mid1;
    Vec2 k2_v = accel(r_mid1, GM);

    Vec2 r_mid2 = {r[0] + 0.5 * dt * k2_r[0], r[1] + 0.5 * dt * k2_r[1]};
    Vec2 v_mid2 = {v[0] + 0.5 * dt * k2_v[0], v[1] + 0.5 * dt * k2_v[1]};
    Vec2 k3_r = v_mid2;
    Vec2 k3_v = accel(r_mid2, GM);

    Vec2 r_end = {r[0] + dt * k3_r[0], r[1] + dt * k3_r[1]};
    Vec2 v_end = {v[0] + dt * k3_v[0], v[1] + dt * k3_v[1]};
    Vec2 k4_r = v_end;
    Vec2 k4_v = accel(r_end, GM);

    for (int i = 0; i &lt; 2; ++i) {
        r[i] += (dt / 6.0) * (k1_r[i] + 2.0 * k2_r[i] + 2.0 * k3_r[i] + k4_r[i]);
        v[i] += (dt / 6.0) * (k1_v[i] + 2.0 * k2_v[i] + 2.0 * k3_v[i] + k4_v[i]);
    }
}

int main() {
    Vec2 r = {1.0, 0.0};
    Vec2 v = {0.0, 1.0};
    double dt = 0.01;

    for (int step = 0; step &lt; 500; ++step) {
        rk4_step(r, v, dt);
    }
    std::cout &lt;&lt; "C++20 RK4 Orbit: Final Position = (" &lt;&lt; r[0] &lt;&lt; ", " &lt;&lt; r[1] &lt;&lt; ")\n";
    return 0;
}


# Julia 1.10: 4th-Order Runge-Kutta Orbital Integrator
function accel(r::Vector{Float64}, GM=1.0)
    norm_r = sqrt(r[1]^2 + r[2]^2)
    return -GM .* r ./ (norm_r^3)
end

function rk4_step(r::Vector{Float64}, v::Vector{Float64}, dt::Float64, GM=1.0)
    k1_r = copy(v)
    k1_v = accel(r, GM)

    k2_r = v .+ 0.5 .* dt .* k1_v
    k2_v = accel(r .+ 0.5 .* dt .* k1_r, GM)

    k3_r = v .+ 0.5 .* dt .* k2_v
    k3_v = accel(r .+ 0.5 .* dt .* k2_r, GM)

    k4_r = v .+ dt .* k3_v
    k4_v = accel(r .+ dt .* k3_r, GM)

    r_next = r .+ (dt / 6.0) .* (k1_r .+ 2.0 .* k2_r .+ 2.0 .* k3_r .+ k4_r)
    v_next = v .+ (dt / 6.0) .* (k1_v .+ 2.0 .* k2_v .+ 2.0 .* k3_v .+ k4_v)
    return r_next, v_next
end

r = [1.0, 0.0]
v = [0.0, 1.0]
dt = 0.01

for _ in 1:500
    global r, v = rk4_step(r, v, dt)
end

println("Julia RK4 Orbit: Final Position = ", r)


program rk4_orbit
    implicit none
    real(8), dimension(2) :: r, v, k1_r, k1_v, k2_r, k2_v, k3_r, k3_v, k4_r, k4_v
    real(8) :: dt, dist, factor
    integer :: step

    r = [1.0d0, 0.0d0]
    v = [0.0d0, 1.0d0]
    dt = 0.01d0

    do step = 1, 500
        ! k1
        k1_r = v
        dist = sqrt(r(1)**2 + r(2)**2)
        k1_v = -r / (dist**3)

        ! k2
        k2_r = v + 0.5d0 * dt * k1_v
        dist = sqrt((r(1)+0.5d0*dt*k1_r(1))**2 + (r(2)+0.5d0*dt*k1_r(2))**2)
        k2_v = -(r + 0.5d0 * dt * k1_r) / (dist**3)

        ! k3
        k3_r = v + 0.5d0 * dt * k2_v
        dist = sqrt((r(1)+0.5d0*dt*k2_r(1))**2 + (r(2)+0.5d0*dt*k2_r(2))**2)
        k3_v = -(r + 0.5d0 * dt * k2_r) / (dist**3)

        ! k4
        k4_r = v + dt * k3_v
        dist = sqrt((r(1)+dt*k3_r(1))**2 + (r(2)+dt*k3_r(2))**2)
        k4_v = -(r + dt * k3_r) / (dist**3)

        ! Update
        r = r + (dt / 6.0d0) * (k1_r + 2.0d0*k2_r + 2.0d0*k3_r + k4_r)
        v = v + (dt / 6.0d0) * (k1_v + 2.0d0*k2_v + 2.0d0*k3_v + k4_v)
    end do

    print *, 'Fortran 2018 RK4 Final Position: ', r
end program rk4_orbit


% MATLAB / GNU Octave: Runge-Kutta 4th-Order Planetary Orbit
function rk4_orbit_demo()
    r = [1.0; 0.0];
    v = [0.0; 1.0];
    dt = 0.01;

    for step = 1:500
        k1_r = v;
        k1_v = -r / norm(r)^3;

        k2_r = v + 0.5 * dt * k1_v;
        k2_v = -(r + 0.5 * dt * k1_r) / norm(r + 0.5 * dt * k1_r)^3;

        k3_r = v + 0.5 * dt * k2_v;
        k3_v = -(r + 0.5 * dt * k2_r) / norm(r + 0.5 * dt * k2_r)^3;

        k4_r = v + dt * k3_v;
        k4_v = -(r + dt * k3_r) / norm(r + dt * k3_r)^3;

        r = r + (dt / 6.0) * (k1_r + 2*k2_r + 2*k3_r + k4_r);
        v = v + (dt / 6.0) * (k1_v + 2*k2_v + 2*k3_v + k4_v);
    end
    fprintf('MATLAB RK4 Final Position: (%.4f, %.4f)\n', r(1), r(2));
end


-- Lean 4: Formal Verification of Autonomous ODE State Transition
import Mathlib.Analysis.Calculus.Deriv.Basic

structure DynamicalState (n : ℕ) where
  position : Fin n → ℝ
  velocity : Fin n → ℝ

-- Definition of a first-order dynamical vector field for Hamiltonian orbit
def KeplerField (r : Fin 2 → ℝ) (v : Fin 2 → ℝ) : (Fin 2 → ℝ) × (Fin 2 → ℝ) :=
  let normSq := (r 0)^2 + (r 1)^2
  let factor := -1.0 / (normSq * Real.sqrt normSq)
