import numpy as np

def rof_denoise_1d(f, lambda_param=1.0, dt=0.01, num_iters=1000, eps=1e-4):
    """
    Rudin-Osher-Fatemi (ROF) 1D Total Variation Denoising.
    Minimizes: \int |u'| dx + (\lambda / 2) \int (u - f)^2 dx
    """
    u = np.copy(f)
    n = len(f)

    for _ in range(num_iters):
        # Forward difference for gradient
        u_x = np.zeros(n)
        u_x[:-1] = u[1:] - u[:-1]

        # Regularized flux: u' / sqrt(u'^2 + eps^2)
        flux = u_x / np.sqrt(u_x**2 + eps**2)

        # Backward divergence: div(flux)
        div_flux = np.zeros(n)
        div_flux[0] = flux[0]
        div_flux[1:-1] = flux[1:-1] - flux[:-2]
        div_flux[-1] = -flux[-2]

        # Euler-Lagrange descent update
        u += dt * (div_flux - lambda_param * (u - f))

    return u

