    for (int it = 0; it &lt; num_iters; ++it) {
        for (size_t i = 0; i &lt; n - 1; ++i) {
            u_x[i] = u[i + 1] - u[i];
            flux[i] = u_x[i] / std::sqrt(u_x[i] * u_x[i] + eps * eps);
        }

        div_flux[0] = flux[0];
        for (size_t i = 1; i &lt; n - 1; ++i) {
            div_flux[i] = flux[i] - flux[i - 1];
        }
        div_flux[n - 1] = -flux[n - 2];

        for (size_t i = 0; i &lt; n; ++i) {
            u[i] += dt * (div_flux[i] - lambda_param * (u[i] - f[i]));
        }
    }
    return u;
