function rof_denoise_1d(f::Vector{Float64}; λ=1.5, dt=0.005, iters=2000, ϵ=1e-4)
    u = copy(f)
    n = length(f)
    flux = zeros(n)
    div_flux = zeros(n)

    for _ in 1:iters
        for i in 1:(n - 1)
            ux = u[i+1] - u[i]
            flux[i] = ux / sqrt(ux^2 + ϵ^2)
        end

        div_flux[1] = flux[1]
        for i in 2:(n - 1)
            div_flux[i] = flux[i] - flux[i-1]
        end
        div_flux[n] = -flux[n-1]

        @. u += dt * (div_flux - λ * (u - f))
    end
    return u
end

