int main() {
    // Direct discretization of J[y] = int [0.5*(y')^2 + y] dx, y(0)=0, y(1)=0
    const int N = 20;
    const double h = 1.0 / N;
    const int m = N - 1;

    // Tridiagonal system solve (Thomas algorithm) for Ay = -b
    // Matrix A: sub= -1/h, diag= 2/h, sup= -1/h. RHS: -h
    std::vector&lt;double&gt; c_prime(m, 0.0), d_prime(m, 0.0), y(m, 0.0);
    double a = -1.0 / h, b_val = 2.0 / h, c = -1.0 / h;
    double d = -h;

    // Forward sweep
    c_prime[0] = c / b_val;
    d_prime[0] = d / b_val;
    for (int i = 1; i &lt; m; ++i) {
        double m_factor = 1.0 / (b_val - a * c_prime[i - 1]);
        c_prime[i] = c * m_factor;
        d_prime[i] = (d - a * d_prime[i - 1]) * m_factor;
    }

    // Back substitution
    y[m - 1] = d_prime[m - 1];
    for (int i = m - 2; i &gt;= 0; --i) {
        y[i] = d_prime[i] - c_prime[i] * y[i + 1];
    }

    std::cout &lt;&lt; std::fixed &lt;&lt; std::setprecision(5);
    std::cout &lt;&lt; "C++20:    Direct Discretization y(0.5) = " &lt;&lt; y[m / 2] &lt;&lt; " (Exact: -0.12500)\n";
    return 0;
}


