import numpy as np

def soft_threshold(v: np.ndarray, gamma: float) -&gt; np.ndarray:
    return np.sign(v) * np.maximum(np.abs(v) - gamma, 0.0)

def ista_lasso(X, y, lmbda: float = 0.1, lr: float = 0.01, n_iter: int = 500):
    w = np.zeros(X.shape[1])
    for _ in range(n_iter):
        # Gradient of smooth loss: 0.5 * ||Xw - y||^2
        grad = X.T @ (X @ w - y)
        # Gradient step followed by proximal soft-thresholding
        w = soft_threshold(w - lr * grad, lr * lmbda)
    return w

