import numpy as np

def implicit_solve_newton(F, J_y, x_val: float, y_init: float, tol: float = 1e-10, max_iter: int = 50):
    # Solves F(x, y) = 0 for y given x
    y = y_init
    for _ in range(max_iter):
        f_val = F(x_val, y)
        if abs(f_val) &lt; tol:
            return y
        dy = J_y(x_val, y)
        y -= f_val / dy
    return y

