#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;cmath&gt;
#include &lt;numeric&gt;

double compute_pinn_loss(const std::vector&lt;double&gt;& u, 
                         const std::vector&lt;double&gt;& d2u, 
                         double omega = 2.0) {
    double total_sq_err = 0.0;
    double omega_sq = omega * omega;
    size_t n = u.size();

    for (size_t i = 0; i &lt; n; ++i) {
        double residual = d2u[i] + omega_sq * u[i];
        total_sq_err += residual * residual;
    }
    return total_sq_err / static_cast&lt;double&gt;(n);
}

